<script setup lang="ts">
import{computed,onUnmounted,ref,watch}from'vue';
import{NAlert,NButton,NCard,NForm,NFormItem,NSelect,NSpace,NSwitch}from'naive-ui';
import{listPolicyView,listPolicyOptions,type ListPolicyView}from'./list-policy-view';
import type{EmployeeHandoffPolicy}from'@dentity/contracts';
import{api,ApiError,errorMessage}from'../../shared/api';
import InfoHint from'../../shared/ui/InfoHint.vue';
const props=defineProps<{base:string;disabled?:boolean}>(),emit=defineEmits<{changed:[];sessionExpired:[];busyChanged:[boolean];dirtyChanged:[boolean]}>();
const policy=ref<EmployeeHandoffPolicy>({version:0,allowAll:true,scope:{mode:'all',allowEmployeeIds:[],denyEmployeeIds:[]}}),original=ref(''),options=ref<{id:string;name:string;enabled:boolean}[]>([]),busy=ref(false),loaded=ref(false),error=ref(''),notice=ref('');let generation=0,controller=new AbortController();
const dirty=computed(()=>loaded.value&&JSON.stringify(policy.value)!==original.value),locked=computed(()=>!!props.disabled||busy.value),employeeOptions=computed(()=>options.value.map(e=>({value:e.id,label:e.name+(e.enabled?'':'（停用）')})));
const selection=computed({get:()=>listPolicyView(policy.value.scope,policy.value.scope.denyEmployeeIds.length),set:(value:ListPolicyView)=>{if(value!=='legacy')policy.value.scope={...policy.value.scope,mode:value==='allowlist'?'allowlist':'all',selectionMode:value};}});
watch(busy,v=>emit('busyChanged',v),{flush:'sync'});watch(dirty,v=>emit('dirtyChanged',v),{flush:'sync'});
async function load(){const version=++generation;controller.abort();controller=new AbortController();const signal=controller.signal;try{busy.value=true;error.value='';const [value,candidates]=await Promise.all([api<EmployeeHandoffPolicy>(props.base+'/handoff-access',signal),api<typeof options.value>(props.base+'/handoff-options',signal)]);if(version!==generation||signal.aborted)return;policy.value=value;options.value=candidates;original.value=JSON.stringify(value);loaded.value=true;}catch(e){if(version===generation&&!signal.aborted){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(version===generation)busy.value=false;}}
async function save(){if(locked.value||!loaded.value)return;const version=generation,signal=controller.signal;busy.value=true;error.value='';notice.value='';try{const value=await api<EmployeeHandoffPolicy>(props.base+'/handoff-access',signal,{expectedVersion:policy.value.version,allowAll:policy.value.allowAll,scope:policy.value.scope},'PUT');if(version!==generation||signal.aborted)return;policy.value=value;original.value=JSON.stringify(value);notice.value='已保存员工接收范围。';emit('changed');}catch(e){if(version===generation&&!signal.aborted){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(version===generation)busy.value=false;}}
function reset(){if(original.value)policy.value=JSON.parse(original.value);error.value='';notice.value='';}
watch(()=>props.base,()=>{loaded.value=false;original.value='';notice.value='';void load();},{immediate:true});onUnmounted(()=>{generation++;controller.abort();emit('busyChanged',false);emit('dirtyChanged',false);});
</script>
<template><NCard title="数字员工交接接收范围" size="small" class="handoff-access"><template #header-extra><InfoHint text="决定哪些同工作区员工可以把任务交接给本员工。能力包默认继承；包的自定义名单只能收窄。只判断直接上一位员工。切换模式保留名单，仅选中名单生效；历史组合规则拒绝优先。关闭事项Beta隐藏并保留配置。" label="交接接收范围说明"/></template><NAlert v-if="error" type="error" role="alert">{{error}}<NButton text :disabled="locked" @click="load">重新读取</NButton></NAlert><NAlert v-if="notice" type="success" role="status">{{notice}}</NAlert><NForm v-if="loaded" @submit.prevent="save"><NFormItem label="允许全部员工交接"><NSwitch v-model:value="policy.allowAll" :disabled="locked" aria-label="允许全部员工交接"/></NFormItem><template v-if="!policy.allowAll"><NFormItem label="自定义接收策略"><NSelect :virtual-scroll="false" v-model:value="selection" :options="listPolicyOptions(selection,'同工作区全部启用员工')" :disabled="locked" aria-label="员工交接接收策略"/></NFormItem><NFormItem v-if="selection==='allowlist'||selection==='legacy'" label="允许交接的来源员工"><NSelect v-model:value="policy.scope.allowEmployeeIds" :options="employeeOptions" multiple filterable :disabled="locked" aria-label="允许交接的来源员工"/></NFormItem><NFormItem v-if="selection==='denylist'||selection==='legacy'" label="拒绝交接的来源员工"><NSelect v-model:value="policy.scope.denyEmployeeIds" :options="employeeOptions" multiple filterable :disabled="locked" aria-label="拒绝交接的来源员工"/></NFormItem></template><NSpace><NButton attr-type="submit" :type="dirty?'primary':'default'" :disabled="locked" :loading="busy">保存交接接收范围</NButton><NButton :disabled="locked||!dirty" @click="reset">取消修改</NButton></NSpace></NForm><NButton v-else :loading="busy" :disabled="locked" @click="load">读取交接接收范围</NButton></NCard></template>
<style scoped>.handoff-access{min-width:0}.handoff-access :deep(.n-alert){margin-bottom:1rem}</style>
